def workspace_registration_helper() -> Path | None:
    override = os.environ.get("LONG_TASK_CONTROL_REGISTER_HELPER")
    if override:
        return Path(override).expanduser().resolve()
    if os.name != "nt":
        return None
    program_data = os.environ.get("ProgramData")
    if not program_data:
        return None
    return Path(program_data) / "LongTaskControl" / "register-workspace.ps1"


def register_workspace_with_local_agent(root: Path) -> bool:
    """Best-effort registration; returns False when no local Agent helper exists."""
    helper = workspace_registration_helper()
    if helper is None or not helper.is_file():
        return False

    if helper.suffix.lower() == ".ps1":
        shell = os.environ.get("LONG_TASK_CONTROL_POWERSHELL")
        if not shell:
            shell = shutil.which("pwsh") or shutil.which("powershell.exe")
        if not shell:
            raise RuntimeError("PowerShell is unavailable")
        command = [
            shell,
            "-NoProfile",
            "-NonInteractive",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            str(helper),
            "-WorkspaceRoot",
            str(root),
        ]
    elif helper.suffix.lower() == ".py":
        command = [sys.executable, str(helper), "--workspace-root", str(root)]
    else:
        command = [str(helper), "--workspace-root", str(root)]

    child_environment = None
    if Path(command[0]).name.lower() == "powershell.exe":
        child_environment = os.environ.copy()
        inherited_module_path = child_environment.get("PSModulePath", "")
        windows_powershell_paths = [
            entry
            for entry in inherited_module_path.split(os.pathsep)
            if "windowspowershell" in entry.lower()
        ]
        if windows_powershell_paths:
            child_environment["PSModulePath"] = os.pathsep.join(windows_powershell_paths)
        else:
            child_environment.pop("PSModulePath", None)

    result = subprocess.run(
        command,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        env=child_environment,
        check=False,
        timeout=15,
    )
    if result.returncode != 0:
        raise RuntimeError(f"registration helper exited with status {result.returncode}")
    return True


